using Yard;
namespace Yard.Cli;
public static class CSharpFormatting {
    private static readonly string[] Excluded=[".git",".yard",".temp","node_modules","bin","obj","dist"];
    public static async Task Run(Workspace workspace,bool check,string? selected,CancellationToken ct) {
        var files=Directory.EnumerateFiles(workspace.Root,"*.cs",SearchOption.AllDirectories).Where(p=>!Path.GetRelativePath(workspace.Root,p).Split(Path.DirectorySeparatorChar).Any(Excluded.Contains)).Where(p=>!File.GetAttributes(p).HasFlag(FileAttributes.ReparsePoint)).Where(p=>!p.EndsWith(".Designer.cs")&&!p.EndsWith("ModelSnapshot.cs")&&!p.EndsWith(".g.cs")&&!p.EndsWith(".generated.cs")).Where(p=>!File.ReadAllText(p).AsSpan(0,Math.Min(2048,File.ReadAllText(p).Length)).Contains("<auto-generated",StringComparison.OrdinalIgnoreCase)).Order().ToArray();
        if(selected!=null){var full=Path.GetFullPath(Path.Combine(workspace.Root,selected));if(!files.Contains(full))throw new YardException("--file must select a non-generated C# source in this repository.",2);files=[full];}
        if(files.Length==0)return;
        var staging=Path.Combine(workspace.State,"format",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(staging);
        var originals=files.ToDictionary(p=>p,File.ReadAllBytes);
        try {
            foreach(var file in files){var relative=Path.GetRelativePath(workspace.Root,file);var target=Path.Combine(staging,relative);Directory.CreateDirectory(Path.GetDirectoryName(target)!);File.WriteAllBytes(target,originals[file]);var parent=Path.GetDirectoryName(file)!;while(parent.StartsWith(workspace.Root,StringComparison.Ordinal)){var config=Path.Combine(parent,".editorconfig");if(File.Exists(config)){var copy=Path.Combine(staging,Path.GetRelativePath(workspace.Root,config));Directory.CreateDirectory(Path.GetDirectoryName(copy)!);File.Copy(config,copy,true);}if(parent==workspace.Root)break;parent=Path.GetDirectoryName(parent)!;}}
            await Processes.Run("dotnet",["csharpier","format",staging,"--no-cache","--log-level","Warning"],workspace.Root,ct);
            await Processes.Run("dotnet",["format","whitespace",staging,"--folder","--verbosity","quiet"],workspace.Root,ct);
            var changes=files.Select(p=>(Path:p,Bytes:File.ReadAllBytes(Path.Combine(staging,Path.GetRelativePath(workspace.Root,p))))).Where(x=>!x.Bytes.SequenceEqual(originals[x.Path])).ToArray();
            if(check){if(changes.Length>0)throw new YardException("C# formatting differs. Run yard fmt.\n"+string.Join("\n",changes.Select(x=>Path.GetRelativePath(workspace.Root,x.Path))));return;}
            if(files.Any(p=>!File.ReadAllBytes(p).SequenceEqual(originals[p])))throw new YardException("A source changed while formatting. Save and retry.");
            foreach(var change in changes){var temporary=change.Path+".yard-format-"+Guid.NewGuid().ToString("N");try{File.WriteAllBytes(temporary,change.Bytes);if(!OperatingSystem.IsWindows())File.SetUnixFileMode(temporary,File.GetUnixFileMode(change.Path));File.Move(temporary,change.Path,true);}finally{File.Delete(temporary);}}
            Console.WriteLine($"Formatted {changes.Length} of {files.Length} C# sources.");
        } finally {Directory.Delete(staging,true);}
    }
}
